	// EVOLVE-BLOCK-START
	// Compute composite scores from all scorers
	scores := make(map[string]float64, len(snapshots))
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			// Clamp to [0,1] per INV-1
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			scores[snap.ID] += s * ws.weights[i]
		}
	}

	// Compute cluster load statistics for adaptive routing
	maxLoad := 0
	minLoad := 999999
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		if el > maxLoad {
			maxLoad = el
		}
		if el < minLoad {
			minLoad = el
		}
	}

	// Load pressure: how heavily loaded is the cluster
	loadPressure := 0.0
	if maxLoad > 0 {
		loadPressure = float64(maxLoad) / (float64(maxLoad) + 4.0)
	}

	// Session and input characteristics
	isSession := req.SessionID != ""
	inputSize := len(req.InputTokens)

	// Dynamic weight adjustment based on request type and cluster state
	dynWeights := make([]float64, len(ws.weights))
	copy(dynWeights, ws.weights)
	if len(dynWeights) >= 2 {
		if isSession {
			// Sessions: strongly favor prefix-affinity
			dynWeights[0] = 2.5
			dynWeights[1] = 0.5
		} else {
			// Non-sessions: shift toward load-balance under pressure
			dynWeights[0] = 1.0 * (1.0 - 0.7*loadPressure)
			dynWeights[1] = 1.0 + 1.5*loadPressure
		}
		// Normalize
		wSum := 0.0
		for _, w := range dynWeights {
			wSum += w
		}
		if wSum > 0.001 {
			for k := range dynWeights {
				dynWeights[k] /= wSum
			}
		}
	}

