	for _, snap := range snapshots {
		el := snap.EffectiveLoad()

		// Cache hit rate bonus (scaled by load idleness)
		scores[snap.ID] += 0.2 * snap.CacheHitRate * (1.0 / (1.0 + 0.1*float64(el)))

