		if inputSize > 512 && snap.FreeKVBlocks > 0 {
			scores[snap.ID] += 0.03 * (float64(snap.FreeKVBlocks) / (float64(snap.FreeKVBlocks) + 100.0))
		}

		// Floor to prevent zero scores
		if scores[snap.ID] < 0.001 {
			scores[snap.ID] = 0.001
		}
	}

